<?php
namespace Tests\Unit;
use PHPUnit\Framework\TestCase;
require_once __DIR__.'/../../scripts/prepare-env.php';
class InstallerTest extends TestCase {
 private string $directory;
 protected function setUp():void {$this->directory=sys_get_temp_dir().'/encuentro-installer-'.bin2hex(random_bytes(8));mkdir($this->directory,0700);copy(__DIR__.'/../../.env.example',$this->directory.'/.env.example');}
 protected function tearDown():void {foreach(glob($this->directory.'/{*,.[!.]*}',GLOB_BRACE) as $file)unlink($file);rmdir($this->directory);}
 private function value(string $key):string {preg_match('/^'.$key.'=(.*)$/m',file_get_contents($this->directory.'/.env'),$m);return trim($m[1]??'');}
 public function test_fresh_install_generates_separate_keys_and_private_env():void {$r=\prepareEnvironment($this->directory);$this->assertTrue($r['created']);$this->assertSame(['APP_KEY','REVERB_APP_KEY','REVERB_APP_SECRET'],$r['generated']);$this->assertSame(32,strlen(base64_decode(substr($this->value('APP_KEY'),7),true)));$this->assertSame(32,strlen($this->value('REVERB_APP_KEY')));$this->assertSame(64,strlen($this->value('REVERB_APP_SECRET')));$this->assertNotSame($this->value('REVERB_APP_KEY'),$this->value('REVERB_APP_SECRET'));$this->assertNotSame('change_me_before_deployment',$this->value('DB_PASSWORD'));$this->assertSame('production',$this->value('APP_ENV'));$this->assertSame('false',$this->value('APP_DEBUG'));$this->assertSame(0600,fileperms($this->directory.'/.env')&0777);}
 public function test_update_keeps_entire_environment_and_all_keys():void {\prepareEnvironment($this->directory);$file=$this->directory.'/.env';file_put_contents($file,"# Mi instalación\n".file_get_contents($file)."PAYMENT_SECRET='opaque-existing-value'\n");$before=file_get_contents($file);$r=\prepareEnvironment($this->directory);$this->assertSame([],$r['generated']);$this->assertSame($before,file_get_contents($file));}
 public function test_existing_app_key_and_db_password_are_never_rotated_for_missing_reverb_keys():void {$key='base64:'.base64_encode(random_bytes(32));file_put_contents($this->directory.'/.env',"APP_KEY={$key}\nDB_PASSWORD=existing-database-password\nAPP_URL=https://reservas.example.com\n");$r=\prepareEnvironment($this->directory);$this->assertSame(['REVERB_APP_KEY','REVERB_APP_SECRET'],$r['generated']);$this->assertSame($key,$this->value('APP_KEY'));$this->assertSame('existing-database-password',$this->value('DB_PASSWORD'));$this->assertStringContainsString('https://reservas.example.com',file_get_contents($this->directory.'/.env'));}
 public function test_quoted_empty_values_are_filled_and_comments_are_preserved():void {file_put_contents($this->directory.'/.env',"# cabecera\r\nAPP_KEY=\"\" # vacía\r\nREVERB_APP_KEY=''\r\nREVERB_APP_SECRET= # falta\r\nCUSTOMER_URL=\"https://mis-reservas.example.com\"\r\n");\prepareEnvironment($this->directory);$text=file_get_contents($this->directory.'/.env');$this->assertStringContainsString("# cabecera\r\n",$text);$this->assertStringContainsString('CUSTOMER_URL="https://mis-reservas.example.com"',$text);$this->assertNotSame('',$this->value('REVERB_APP_SECRET'));}
 public function test_existing_invalid_key_aborts_without_changing_file():void {$file=$this->directory.'/.env';$before="APP_KEY=invalid-existing-key\n";file_put_contents($file,$before);try{\prepareEnvironment($this->directory);$this->fail('debe rechazar clave existente inválida');}catch(\RuntimeException $e){$this->assertStringContainsString('restaura la clave original',$e->getMessage());}$this->assertSame($before,file_get_contents($file));}
 public function test_duplicate_keys_abort_without_rewriting_existing_secrets():void {$file=$this->directory.'/.env';$before="APP_KEY=\nAPP_KEY=\n";file_put_contents($file,$before);try{\prepareEnvironment($this->directory);$this->fail('debe rechazar duplicados');}catch(\RuntimeException $e){$this->assertStringContainsString('duplicada',$e->getMessage());}$this->assertSame($before,file_get_contents($file));}
 public function test_env_symlink_is_rejected_without_touching_target():void {$target=$this->directory.'/other';file_put_contents($target,'unchanged');symlink($target,$this->directory.'/.env');$this->expectException(\RuntimeException::class);try{\prepareEnvironment($this->directory);}finally{$this->assertSame('unchanged',file_get_contents($target));}}
}
